  foreach($a->all("SELECT minutes,package_label,note,customer_name FROM {{shoot_bookings}} WHERE shoot_day=? AND status='active' ORDER BY minutes",[$day]) as $r){$from=day_time($day)+(int)$r['minutes']*60000;$to=$from+booking_length($r['package_label'],$r['note'])*60000;if($to<=$in)continue;$count++;if($out===null||$to>=$out){$out=$to;$last=['time'=>booking_hm((int)$r['minutes']),'customer_name'=>$r['customer_name'],'package_label'=>$r['package_label']];}}
