 // Chấm hộ cả ca (chủ dự án yêu cầu 09/11/2026: chấm được mọi trường hợp, chấm 1 lần là ghi nhận ca, không bắt ghi chú, không bắt theo thứ tự vào/ra):
 // ghi thẳng lượt vào + ra vào đúng ca/ngày, không xét lượt của ca/ngày khác. Ca đang mở (có vào chưa ra) thì chỉ thêm lượt ra; ca đã đủ vào/ra thì báo đã tính công.
 if($path==='/attendance/manual-shift'&&$method==='POST'){if(!is_int($b['user_id']??null))fail('Chọn nhân viên.');$uid=$b['user_id'];if($a->target($uid)['role']!=='employee')fail('Chỉ chấm hộ cho tài khoản Nhân viên.');$shift=$b['shift']??'';if(!in_array($shift,['day_first','day_second','ot'],true))fail('Chọn Ca 1, Ca 2 hoặc OT.');$ot=$shift==='ot';$in=$b['in_time']??null;$out=$b['out_time']??null;if(!is_int($in)||!is_int($out)||$in<1577836800000||$out<=$in)fail('Giờ ra phải sau giờ vào.');
  $day=local_day($in);if($day>local_day(now_ms()))fail('Không chấm hộ cho ngày chưa tới.');if($ot){if($out-$in>12*3600000)fail('Lượt OT tối đa 12 tiếng.');if(($b['ot_confirmed']??false)!==true)fail('Xác nhận nhân viên thực sự làm OT trước khi chấm hộ.');}elseif(local_day($out)!==$day)fail('Giờ vào và giờ ra phải cùng một ngày.');
  $reason=trim(is_string($b['reason']??null)?$b['reason']:'');if(mb_strlen($reason)>500)fail('Ghi chú tối đa 500 ký tự.');if($reason==='')$reason='Chấm hộ cả '.($ot?'lượt OT':'ca').'.';$a->assertOpen($in);$a->assertOpen($out);
  $own=$a->all('SELECT id,type,time FROM {{events}} WHERE user_id=? AND shift=? AND work_date=? ORDER BY time,id',[$uid,$shift,$day]);$last=$own?end($own):null;
  if($last&&$last['type']==='out')return [200,['ok'=>true,'ids'=>[],'existing'=>true]];
  if($last&&$out<=(int)$last['time'])fail('Ca này đã có lượt vào lúc '.gmdate('H:i',intdiv((int)$last['time'],1000)+25200).'. Giờ ra phải sau giờ đó.');
  $add=$last?[['out',$out]]:[['in',$in],['out',$out]];$now=now_ms();$ids=[];
  foreach($add as [$type,$t]){if(!$ot&&$type==='in'&&function_exists('freeze_booking_shift'))freeze_booking_shift($a,$uid,$day,$shift);
   $a->run('INSERT INTO {{events}}(user_id,type,time,distance,accuracy,shift,work_date,ot_confirmed_at,photo_jpeg,source,recorded_by,recorded_at,reason) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',[$uid,$type,$t,null,null,$shift,$day,$ot&&$type==='in'?$now:null,null,'manual',$a->user['id'],$now,$reason]);$ids[]=(int)$a->db->lastInsertId();}
  $a->audit($uid,'manual_attendance');return [201,['ok'=>true,'ids'=>$ids,'closed_only'=>(bool)$last]];}
 if($path==='/attendance/manual'&&$method==='POST'){validate_correction($b);if(!is_int($b['user_id']??null))fail('Chọn nhân viên.');if($a->target($b['user_id'])['role']!=='employee')fail('Chỉ chấm hộ cho tài khoản Nhân viên.');$id=$a->insertEvent($b,$b['user_id'],true);return [201,['ok'=>true,'id'=>$id]];}
 return null;
}
function validate_correction(array $b): void {if(!in_array($b['shift']??'', ['day_first','day_second','ot'],true)||!in_array($b['type']??'', ['in','out'],true)||!is_int($b['time']??null)||$b['time']<1577836800000||$b['time']>now_ms()||!is_string($b['reason']??null)||strlen(trim($b['reason']))<10||strlen($b['reason'])>1500)fail('Chọn ca, lượt chấm, giờ không ở tương lai và lý do từ 10–500 ký tự.');}
